// Feature discovery.
//
// 1. features.json — generated by scripts/build-features.mjs (run locally via
//    `npm run build`, and automatically by the GitHub Pages workflow).
// 2. GitHub contents API — fallback for when the site is served straight from
//    a branch on *.github.io without the build step.

const HIDDEN = /^[._]/;

const titleCase = (name) => name.replace(/[-_]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());

export async function discoverFeatures() {
  try {
    const res = await fetch('features.json', { cache: 'no-cache' });
    if (res.ok) {
      const data = await res.json();
      return { source: 'manifest', features: data.features ?? [] };
    }
  } catch {
    // Fall through to the GitHub fallback.
  }

  const repo = githubRepoFromLocation();
  if (repo) {
    try {
      return { source: 'github', features: await discoverViaGitHub(repo) };
    } catch (err) {
      console.warn('GitHub feature discovery failed:', err);
    }
  }

  return { source: 'none', features: [] };
}

// owner.github.io/repo/ → { owner, repo }; owner.github.io/ → { owner, repo: "owner.github.io" }
function githubRepoFromLocation() {
  const host = location.hostname.match(/^([^.]+)\.github\.io$/i);
  if (!host) return null;
  const owner = host[1];
  const first = location.pathname.split('/').filter(Boolean)[0];
  const isProjectSite = first && first !== 'features' && !first.includes('.');
  return { owner, repo: isProjectSite ? first : `${owner}.github.io` };
}

async function githubJson(url) {
  const res = await fetch(url, { headers: { Accept: 'application/vnd.github+json' } });
  if (!res.ok) throw new Error(`GitHub API ${res.status}`);
  return res.json();
}

// Same rules as scripts/build-features.mjs: any features/**/index.html is a
// feature unless a parent directory is already a feature or a segment is hidden.
async function discoverViaGitHub({ owner, repo }) {
  const api = `https://api.github.com/repos/${owner}/${repo}`;
  const { default_branch: branch } = await githubJson(api);
  const { tree } = await githubJson(`${api}/git/trees/${encodeURIComponent(branch)}?recursive=1`);

  const candidates = tree
    .map((e) => e.type === 'blob' && e.path.match(/^features\/(.+)\/index\.html$/)?.[1])
    .filter((id) => id && !id.split('/').some((s) => HIDDEN.test(s)))
    .sort((a, b) => a.split('/').length - b.split('/').length);
  const ids = [];
  for (const id of candidates) {
    if (!ids.some((parent) => id.startsWith(parent + '/'))) ids.push(id);
  }

  const features = (await Promise.all(ids.map(readFeature))).filter(Boolean);
  return features.sort(
    (a, b) => (a.order ?? Infinity) - (b.order ?? Infinity) || a.title.localeCompare(b.title),
  );
}

async function readFeature(id) {
  const path = `features/${id}/`;
  const htmlRes = await fetch(`${path}index.html`);
  if (!htmlRes.ok) return null;

  const doc = new DOMParser().parseFromString(await htmlRes.text(), 'text/html');
  const meta = (name) => doc.querySelector(`meta[name="${name}"]`)?.content?.trim();
  let info = {
    title: doc.title?.trim(),
    description: meta('description'),
    icon: meta('feature-icon'),
    tags: meta('feature-tags')?.split(',').map((t) => t.trim()).filter(Boolean),
  };

  try {
    const jsonRes = await fetch(`${path}feature.json`);
    if (jsonRes.ok) info = { ...info, ...(await jsonRes.json()) };
  } catch {
    // feature.json is optional.
  }

  const segments = id.split('/');
  const groupSegments = segments.slice(0, -1);
  return {
    id,
    path,
    group: groupSegments.join('/'),
    groupTitle: groupSegments.map(titleCase).join(' / '),
    title: info.title || titleCase(segments.at(-1)),
    description: info.description || '',
    icon: info.icon || '',
    tags: Array.isArray(info.tags) ? info.tags : [],
    order: Number.isFinite(info.order) ? info.order : null,
  };
}
